116	#[test]
117	fn handles_multiple_placeholders() {
118	    // `static` scenario data inside the test fn matches the
119	    // pattern from
120	    // [pnpm/pacquet#339](https://github.com/pnpm/pacquet/issues/339):
121	    // keep the fake stateless by stashing variation in a `static`,
122	    // not in `&self`.
123	    static ENV: &[(&str, &str)] = &[("A", "1"), ("B", "2")];
124	    struct StaticEnv;
125	    impl EnvVar for StaticEnv {
126	        fn var(name: &str) -> Option<String> {
127	            ENV.iter().find(|(key, _)| *key == name).map(|(_, value)| (*value).to_owned())
128	        }
129	    }
130	    assert_eq!(replace_clean::<StaticEnv>("${A}-${B}-${A}"), "1-2-1");
131	}
