        output.truncate(output.len() - backslashes);
        for _ in 0..(backslashes / 2) {
            output.push('\\');
        }

        let placeholder = &text[index..=end];
        if backslashes % 2 == 1 {
            // Odd backslashes: the placeholder is escaped, leave it literal.
            output.push_str(placeholder);
